<body>
    <div class="header">
        <div class="back-btn" id="backBtn">← 返回</div>
        <button class="mode-toggle" id="modeToggle">黑夜模式</button>
    </div>

    <div class="book-container">
        <div class="book-page" id="bookPage">
            <div class="book-title">$1</div>
            <div class="book-content" id="bookContent">
                <!-- 正文内容将通过JavaScript自动分段 -->
            </div>
        </div>
    </div>

    <div class="controls">
        <button class="chapter-btn" id="prevChapterBtn">上一章</button>
        <button class="catalog-btn" id="catalogBtn">目录</button>
        <button class="chapter-btn" id="nextChapterBtn">下一章</button>
    </div>

    <div class="catalog-overlay" id="catalogOverlay">
        <div class="catalog-panel">
            <div class="catalog-title">目录</div>
            <div class="catalog-content" id="catalogContent">
                <!-- 目录内容将通过JavaScript动态生成 -->
            </div>
        </div>
    </div>

    <script>
        // 小说正文内容 - 使用定位符
        const novelContent = `$2`;

        // 目录内容 - 使用定位符
        const catalogData = `$3`;

        // 获取DOM元素
        const backBtn = document.getElementById('backBtn');
        const bookPage = document.getElementById('bookPage');
        const bookContent = document.getElementById('bookContent');
        const prevChapterBtn = document.getElementById('prevChapterBtn');
        const nextChapterBtn = document.getElementById('nextChapterBtn');
        const catalogBtn = document.getElementById('catalogBtn');
        const catalogOverlay = document.getElementById('catalogOverlay');
        const catalogContent = document.getElementById('catalogContent');
        const modeToggle = document.getElementById('modeToggle');
        const body = document.body;

        // 自动分段函数
        function autoParagraph(text) {
            if (!text || text.trim() === '') return '';

            const sentences = text.split(/(?<=[。！？；;!?])/g);
            const nonEmptySentences = sentences.filter(s => s.trim().length > 0);

            return nonEmptySentences.map(sentence => 
                `<p>${sentence.trim()}</p>`
            ).join('');
        }

        // 目录格式化函数
        function formatCatalog(content) {
            if (!content || content.trim() === '') return '';

            const chapters = content.split('\n').filter(chap => chap.trim() !== '');
            if (chapters.length === 0) return '';

            return chapters.map(chapter => 
                `<div class="chapter-item">${chapter.trim()}</div>`
            ).join('');
        }

        // 发送消息给AI的函数
        function sendToAI(message) {
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            } else {
                console.log('AI交互环境未检测到，将发送:', message);
                alert('消息已准备发送给AI：\n\n' + message);
            }
        }

        // 初始化页面内容
        function initPage() {
            document.title = `$1 - 喵喵小说`;

            const formattedContent = autoParagraph(novelContent);
            bookContent.innerHTML = formattedContent;

            const formattedCatalog = formatCatalog(catalogData);
            catalogContent.innerHTML = formattedCatalog;

            bookPage.classList.add('page-turn-animation');
            setTimeout(() => {
                bookPage.classList.remove('page-turn-animation');
            }, 800);
        }

        // 返回按钮点击事件
        backBtn.addEventListener('click', function() {
            sendToAI('返回书库');
        });

        // 上一章按钮点击事件
        prevChapterBtn.addEventListener('click', function() {
            bookPage.classList.add('page-turn-animation');
            sendToAI('上一章');
            setTimeout(() => {
                bookPage.classList.remove('page-turn-animation');
            }, 800);
        });

        // 下一章按钮点击事件
        nextChapterBtn.addEventListener('click', function() {
            bookPage.classList.add('page-turn-animation');
            sendToAI('下一章');
            setTimeout(() => {
                bookPage.classList.remove('page-turn-animation');
            }, 800);
        });

        // 目录按钮点击事件
        catalogBtn.addEventListener('click', function() {
            catalogOverlay.classList.add('active');
        });

        // 点击目录 overlay 关闭目录
        catalogOverlay.addEventListener('click', function(e) {
            if (e.target === catalogOverlay) {
                catalogOverlay.classList.remove('active');
            }
        });

        // 黑夜/白天模式切换
        let isNightMode = false;
        modeToggle.addEventListener('click', function() {
            isNightMode = !isNightMode;
            if (isNightMode) {
                body.classList.add('night-mode');
                modeToggle.textContent = '白天模式';
            } else {
                body.classList.remove('night-mode');
                modeToggle.textContent = '黑夜模式';
            }
        });

        // 页面加载完成后初始化
        window.addEventListener('load', initPage);
    </script>
</body>
</html>
