        // DOM元素
        const booksContainer = document.getElementById('booksContainer');
        const customPage = document.getElementById('customPage');
        const categoryPage = document.getElementById('categoryPage');
        const libraryTab = document.getElementById('libraryTab');
        const categoryTab = document.getElementById('categoryTab');
        const customTab = document.getElementById('customTab');
        const searchInput = document.getElementById('searchInput');
        const searchBtn = document.getElementById('searchBtn');
        const refreshBtn = document.getElementById('refreshBtn');
        const startCustomBtn = document.getElementById('startCustomBtn');
        const toast = document.getElementById('toast');
        const maleTagsContainer = document.getElementById('maleTags');
        const femaleTagsContainer = document.getElementById('femaleTags');
        const maleContent = document.getElementById('maleContent');
        const femaleContent = document.getElementById('femaleContent');
        const categoryTabs = document.querySelectorAll('.category-tab');
        const novelTypes = document.querySelectorAll('.novel-type');
        const styleDropdownBtn = document.getElementById('styleDropdownBtn');
        const styleDropdown = document.getElementById('styleDropdown');
        const longStyleSetting = document.getElementById('longStyleSetting');
        const styleDropdownItems = document.querySelectorAll('.style-dropdown-item');

        // 初始化书籍列表
        function renderBooks(booksToRender) {
            booksContainer.innerHTML = '';

            if (booksToRender.length === 0) {
                booksContainer.innerHTML = '<p class="no-books">没有找到相关书籍</p>';
                return;
            }

            booksToRender.forEach(book => {
                const bookElement = document.createElement('div');
                bookElement.className = 'book-item';
                bookElement.innerHTML = `
                    <div class="book-cover">${book.cover}</div>
                    <div class="book-info">
                        <div class="book-title">${book.title}</div>
                        <div class="book-author">作者：${book.author}</div>
                        <div class="book-desc">${book.desc}</div>
                        <div class="book-tags">
                            ${book.tags.map(tag => `<span class="tag">${tag}</span>`).join('')}
                        </div>
                    </div>
                `;

                bookElement.addEventListener('click', () => {
                    // 发送给AI的信息
                    sendToAI(`点击书籍：《${book.title}》，作者：${book.author}`);
                });

                booksContainer.appendChild(bookElement);
            });
        }

        // 初始化标签布局
        function initTags() {
            // 清空标签容器
            maleTagsContainer.innerHTML = '';
            femaleTagsContainer.innerHTML = '';

            // 添加男性频道标签
            renderTagGroups(maleTags, maleTagsContainer);

            // 添加女性频道标签
            renderTagGroups(femaleTags, femaleTagsContainer);
        }

        // 渲染标签组（每5个标签为一组，组间用虚线分隔）
        function renderTagGroups(tags, container) {
            const groupSize = 5;

            for (let i = 0; i < tags.length; i += groupSize) {
                const tagGroup = document.createElement('div');
                tagGroup.className = 'tag-group';

                for (let j = i; j < i + groupSize && j < tags.length; j++) {
                    const tag = tags[j];
                    const tagElement = document.createElement('div');
                    tagElement.className = 'category-tag';

                    const tagContent = document.createElement('div');
                    tagContent.className = 'tag-content';
                    tagContent.textContent = tag;
                    tagContent.title = tag; // 添加标题提示，用于长标签显示完整内容

                    tagContent.addEventListener('click', () => {
                        // 判断当前是男性频道还是女性频道
                        const isMale = container.id === 'maleTags';
                        const channel = isMale ? '男性频道' : '女性频道';
                        sendToAI(`选择标签：${tag}（${channel}）`);
                    });

                    tagElement.appendChild(tagContent);
                    tagGroup.appendChild(tagElement);
                }

                container.appendChild(tagGroup);
            }
        }

        // 清空输入框
        function clearField(fieldId) {
            document.getElementById(fieldId).value = '';
        }

        // 显示提示消息
        function showToast(message) {
            toast.textContent = message;
            toast.style.display = 'block';
            setTimeout(() => {
                toast.style.display = 'none';
            }, 2000);
        }

        // 发送消息给AI
        function sendToAI(message) {
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            } else {
                console.log('AI交互环境未检测到，将发送:', message);
                // 在实际环境中，这里可以替换为实际的AI接口调用
                alert('消息已准备发送给AI：\n\n' + message);
            }
        }

        // 搜索功能
        function performSearch() {
            const keyword = searchInput.value.trim();
            if (keyword) {
                const filteredBooks = books.filter(book => 
                    book.title.includes(keyword) || 
                    book.author.includes(keyword) || 
                    book.tags.some(tag => tag.includes(keyword))
                );
                renderBooks(filteredBooks);
                sendToAI(`搜索小说："${keyword}"`);
            } else {
                renderBooks(books);
            }
        }

        // 刷新功能
        function refreshBooks() {
            renderBooks(books);
            sendToAI('刷新书库');
        }

        // 定制小说功能
        function startCustomNovel() {
            const isShortStory = document.querySelector('.novel-type.active').getAttribute('data-type') === 'short';

            if (isShortStory) {
                // 短篇小说
                const character = document.getElementById('characterSetting').value;
                const location = document.getElementById('locationSetting').value;
                const plot = document.getElementById('plotSetting').value;
                const detail = document.getElementById('detailSetting').value;

                if (!character || !location || !plot) {
                    showToast('请至少填写人物设定、地点场所和故事情节');
                    return;
                }

                const message = `定制短篇小说：人物设定-${character}，地点场所-${location}，故事情节-${plot}，细节说明-${detail}`;
                sendToAI(message);
            } else {
                // 长篇小说
                const worldView = document.getElementById('worldView').value;
                const character = document.getElementById('longCharacterSetting').value;
                const mainPlot = document.getElementById('mainPlot').value;
                const style = document.getElementById('longStyleSetting').value;
                const chapter = document.getElementById('longChapterSetting').value;
                const wordsPerChapter = document.getElementById('longWordsPerChapter').value;

                if (!worldView || !character || !mainPlot) {
                    showToast('请至少填写世界观、人物设定和主线剧情框架');
                    return;
                }

                if (!wordsPerChapter) {
                    showToast('请填写每章字数');
                    return;
                }

                const message = `定制长篇小说：世界观-${worldView}，人物设定-${character}，主线剧情框架-${mainPlot}，文风设定-${style}，章节设定-${chapter}，每章字数-${wordsPerChapter}字`;
                sendToAI(message);
            }
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', () => {
            // 渲染初始书籍列表
            renderBooks(books);

            // 初始化标签布局
            initTags();

            // 搜索按钮点击事件
            searchBtn.addEventListener('click', performSearch);

            // 回车键搜索
            searchInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    performSearch();
                }
            });

            // 刷新按钮点击事件
            refreshBtn.addEventListener('click', refreshBooks);

            // 标签切换
            libraryTab.addEventListener('click', () => {
                libraryTab.classList.add('active');
                categoryTab.classList.remove('active');
                customTab.classList.remove('active');
                booksContainer.style.display = 'block';
                categoryPage.style.display = 'none';
                customPage.style.display = 'none';
            });

            categoryTab.addEventListener('click', () => {
                categoryTab.classList.add('active');
                libraryTab.classList.remove('active');
                customTab.classList.remove('active');
                booksContainer.style.display = 'none';
                categoryPage.style.display = 'block';
                customPage.style.display = 'none';
            });

            customTab.addEventListener('click', () => {
                customTab.classList.add('active');
                libraryTab.classList.remove('active');
                categoryTab.classList.remove('active');
                booksContainer.style.display = 'none';
                categoryPage.style.display = 'none';
                customPage.style.display = 'block';
            });

            // 分类标签切换
            categoryTabs.forEach(tab => {
                tab.addEventListener('click', () => {
                    const tabName = tab.getAttribute('data-tab');

                    // 移除所有标签的active类
                    categoryTabs.forEach(t => t.classList.remove('active'));
                    // 添加当前标签的active类
                    tab.classList.add('active');

                    // 隐藏所有内容
                    document.querySelectorAll('.category-content').forEach(content => {
                        content.classList.remove('active');
                    });

                    // 显示当前标签对应的内容
                    document.getElementById(`${tabName}Content`).classList.add('active');
                });
            });

            // 小说类型切换
            novelTypes.forEach(type => {
                type.addEventListener('click', () => {
                    const typeName = type.getAttribute('data-type');

                    // 移除所有类型的active类
                    novelTypes.forEach(t => t.classList.remove('active'));
                    // 添加当前类型的active类
                    type.classList.add('active');

                    // 隐藏所有表单
                    document.querySelectorAll('.novel-form').forEach(form => {
                        form.classList.remove('active');
                    });

                    // 显示当前类型对应的表单
                    document.getElementById(`${typeName}StoryForm`).classList.add('active');
                });
            });

            // 文风下拉菜单功能
            styleDropdownBtn.addEventListener('click', () => {
                styleDropdown.style.display = styleDropdown.style.display === 'block' ? 'none' : 'block';
            });

            // 点击文风选项
            styleDropdownItems.forEach(item => {
                item.addEventListener('click', () => {
                    const styleName = item.getAttribute('data-value');
                    const styleDescription = styleDescriptions[styleName];
                    longStyleSetting.value = styleDescription;
                    styleDropdown.style.display = 'none';
                });
            });

            // 点击页面其他地方关闭下拉菜单
            document.addEventListener('click', (e) => {
                if (!e.target.closest('.style-input-container')) {
                    styleDropdown.style.display = 'none';
                }
            });

            // 开始定制按钮点击事件
            startCustomBtn.addEventListener('click', startCustomNovel);
        });
    </script>
</body>
</html>
